const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export type Step = QuoteStep;

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

function quote(step: QuoteStep): QuoteResult {
  const policyBase = step.items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );

  const itemSurcharges = step.items.reduce(
    (sum, item) =>
      sum + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE : 0),
    0,
  );

  const premium =
    policyBase +
    itemSurcharges +
    policyBase * FIRST_INSURANCE_SURCHARGE +
    PROCESSING_FEE;

  return { premium: Math.ceil(premium) };
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return {
    results: scenario.steps.map((step) => quote(step)),
  };
}

