  const quoteComponents = (types: string[]): number => {
    const { results } = runScenario({
      customer: { yearsWithMHPCO: 2 },
      steps: [{ op: "quote", items: types.map((type) => ({ type })) }],
    });
    // A 2-year customer's loyalty discount (20%) exactly cancels the
    // first-insurance surcharge (10%) plus... no: 20% - 10% = 10% net discount.
    // Recover the raw policy base premium from the returned premium instead.
    return results[0].premium;
  };

  test("two alike components are charged individually", () => {
    // base 50 G, net policy modifier -10% => 45 G + 5 G fee
    expect(quoteComponents(["rune", "rune"])).toBe(50);
  });

  test("exactly three alike components form a discounted block", () => {
    // base 60 G (block), net policy modifier -10% => 54 G + 5 G fee
    expect(quoteComponents(["rune", "rune", "rune"])).toBe(59);
  });

  test("four alike components do not form a block", () => {
    // base 100 G, net -10% => 90 G + 5 G fee
    expect(quoteComponents(["rune", "rune", "rune", "rune"])).toBe(95);
  });

  test("seven alike components form two blocks and one single", () => {
    // base 175 G (60 + 60 + 25 + 25 + ... ) -> see prompt: 7 runes = 175 G
    // net -10% => 157.5 G + 5 G fee = 162.5 -> 163 G (rounded up)
    expect(quoteComponents(["rune", "rune", "rune", "rune", "rune", "rune", "rune"])).toBe(163);
  });

  test("components of different types do not form a block together", () => {
    // base 75 G, net -10% => 67.5 G + 5 G fee = 72.5 -> 73 G (rounded up)
    expect(quoteComponents(["rune", "rune", "moonstone"])).toBe(73);
  });

  test("each component type forms its own block", () => {
    // base 120 G (two blocks), net -10% => 108 G + 5 G fee
    expect(quoteComponents(["rune", "rune", "rune", "moonstone", "moonstone", "moonstone"])).toBe(113);
  });
});

